import glom

class Cli(glom.Cli):
    def __init__(self, *args, **kwargs):
        self.specs = [glom.specify()] + list(args)
        super().__init__(*args, **kwargs)

    def run(self):
        for spec in self.specs:
            glom.parse(spec, self.root, self.context)

        return self.root

if __name__ == '__main__':
    cli = Cli()
    cli.run()
